/* @autogenerated */
package net.civeira.phylax.features.oauth.delegatelogin.infrastructure.driven;

import java.time.Clock;
import java.util.List;
import java.util.Objects;
import java.util.Optional;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.transaction.Transactional;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.civeira.phylax.features.access.tenant.domain.Tenant;
import net.civeira.phylax.features.access.tenantloginprovider.domain.TenantLoginProvider;
import net.civeira.phylax.features.access.tenantloginprovider.domain.TenantLoginProviderAccountLinkPolicyOptions;
import net.civeira.phylax.features.access.tenantloginprovider.domain.TenantLoginProviderProviderTypeOptions;
import net.civeira.phylax.features.access.tenantloginprovider.domain.gateway.TenantLoginProviderFilter;
import net.civeira.phylax.features.access.tenantloginprovider.domain.gateway.TenantLoginProviderQueryRepositoryGateway;
import net.civeira.phylax.features.access.user.domain.User;
import net.civeira.phylax.features.access.user.domain.UserChangeSet;
import net.civeira.phylax.features.access.user.domain.gateway.UserCommandRepositoryGateway;
import net.civeira.phylax.features.access.user.domain.gateway.UserFilter;
import net.civeira.phylax.features.oauth.authentication.domain.AuthRequest;
import net.civeira.phylax.features.oauth.delegatelogin.domain.DelegatedAccessExternalProvider;
import net.civeira.phylax.features.oauth.delegatelogin.domain.FederatedUser;
import net.civeira.phylax.features.oauth.delegatelogin.domain.PendingDelegation;
import net.civeira.phylax.features.oauth.delegatelogin.domain.gateway.DelegatedAccessProviderGateway;
import net.civeira.phylax.features.oauth.delegatelogin.domain.gateway.FederatedIdentityGateway;
import net.civeira.phylax.features.oauth.delegatelogin.domain.provider.GoogleDelegatedAccessProvider;
import net.civeira.phylax.features.oauth.delegatelogin.domain.provider.SamlDelegatedAccessProvider;
import net.civeira.phylax.features.oauth.user.infrastructure.ActiveUserFindService;

/**
 * Provider registry and account resolution for delegated login.
 *
 * Responsibilities: - Build the providers configured for a tenant. - Resolve a validated external
 * identity into a local account following the provider link policy.
 *
 * Design notes: - Accounts are reached through links (provider record, subject), never by display
 * name. - Same resolution rules as the PHP DelegateLoginAdapter (task 072).
 */
@Slf4j
@ApplicationScoped
@RequiredArgsConstructor
public class DelegatedAccessAuthValidatorAdapter implements DelegatedAccessProviderGateway {
  /**
   * Reader for the provider metadata JSON.
   */
  private static final ObjectMapper MAPPER = new ObjectMapper();

  private final ActiveUserFindService actives;
  private final UserCommandRepositoryGateway usersWriter;
  private final TenantLoginProviderQueryRepositoryGateway providers;
  private final FederatedIdentityGateway identities;

  @Override
  public List<DelegatedAccessExternalProvider> providers(AuthRequest request) {
    return actives.findEnabledTenant(request.getTenant(), request.getAudiences())
        .map(this::providers).orElseGet(List::of);
  }

  /**
   * Resolves the account of a validated identity.
   *
   * <ol>
   * <li>without subject: refused;</li>
   * <li>subject already linked to an account of this tenant with this provider: that account,
   * whatever email comes now;</li>
   * <li>{@code manual} policy: only existing links are valid;</li>
   * <li>email not verified by the provider: refused;</li>
   * <li>existing account with that email: joined if the policy allows it;</li>
   * <li>new email: the account is created.</li>
   * </ol>
   * Each allowed access records its link.
   */
  @Override
  @Transactional
  public Optional<String> resolveAccount(AuthRequest request, String provider, FederatedUser user) {
    Optional<Tenant> found = actives.findEnabledTenant(request.getTenant(), request.getAudiences());
    if (found.isEmpty()) {
      return Optional.empty();
    }
    Tenant tenant = found.get();
    Optional<TenantLoginProvider> configured = provider(tenant, provider);
    if (configured.isEmpty()) {
      return refuse(tenant, provider, "unknown_provider");
    }
    TenantLoginProvider loginProvider = configured.get();
    String subject = user.getSubject();
    if (subject.isBlank()) {
      return refuse(tenant, provider, "missing_subject");
    }
    Optional<User> linked = identities.linkedUser(loginProvider.getUid(), subject)
        .flatMap(uid -> accountInTenant(uid, tenant));
    if (linked.isPresent()) {
      return enabled(linked.get());
    }
    if (policy(loginProvider) == TenantLoginProviderAccountLinkPolicyOptions.MANUAL) {
      return refuse(tenant, provider, "account_link_not_allowed");
    }
    if (!user.isEmailVerified() || user.email().isEmpty()) {
      return refuse(tenant, provider, "unverified_email");
    }
    String email = user.email().get();
    Optional<User> existing =
        usersWriter.findForUpdate(UserFilter.builder().name(email).tenant(tenant).build());
    if (existing.isPresent() && !mayJoin(existing.get(), loginProvider, tenant)) {
      return refuse(tenant, provider, "account_link_not_allowed");
    }
    User account = existing
        .orElseGet(() -> usersWriter.create(User.create(new UserChangeSet().newUid().name(email)
            .email(email).emailVerified(true).passwordPlain(PendingDelegation.newSecret())
            .federatedProvider(loginProvider.getProviderType().name())
            .enabled(loginProvider.isUsersEnabledByDefault()).tenant(tenant))));
    String winner = identities.link(loginProvider.getUid(), subject, account.getUid());
    if (!winner.equals(account.getUid())) {
      // A concurrent sign-in of the same subject linked it first: the subject's account is that
      // one.
      Optional<User> other = accountInTenant(winner, tenant);
      if (other.isEmpty()) {
        return refuse(tenant, provider, "account_link_conflict");
      }
      account = other.get();
    }
    return enabled(account);
  }

  private Optional<String> enabled(User account) {
    return actives.checkEnabled(account) ? Optional.of(account.getName()) : Optional.empty();
  }

  private Optional<User> accountInTenant(String userUid, Tenant tenant) {
    return usersWriter.retrieveForUpdate(userUid, Optional.empty())
        .filter(user -> Objects.equals(user.getTenant().getUid(), tenant.getUid()));
  }

  /**
   * Whether an existing account with the asserted email may be joined.
   *
   * {@code verified-email} joins it. {@code none} only when this provider already reaches it with
   * another subject, or when it created the account before links were recorded: same provider type,
   * no links, and the only enabled provider of that type in the tenant.
   */
  private boolean mayJoin(User account, TenantLoginProvider provider, Tenant tenant) {
    if (policy(provider) == TenantLoginProviderAccountLinkPolicyOptions.VERIFIED_EMAIL) {
      return true;
    }
    if (identities.isLinkedTo(account.getUid(), provider.getUid())) {
      return true;
    }
    return account.getFederatedProvider().filter(provider.getProviderType().name()::equals)
        .isPresent() && !identities.hasLinks(account.getUid())
        && enabledProvidersOf(provider.getProviderType(), tenant) == 1;
  }

  private long enabledProvidersOf(TenantLoginProviderProviderTypeOptions source, Tenant tenant) {
    return listProviders(tenant).stream()
        .filter(provider -> Boolean.TRUE.equals(provider.isEnabled())
            && provider.getProviderType() == source)
        .count();
  }

  private static TenantLoginProviderAccountLinkPolicyOptions policy(TenantLoginProvider provider) {
    return Optional.ofNullable(provider.getAccountLinkPolicy())
        .orElse(TenantLoginProviderAccountLinkPolicyOptions.VERIFIED_EMAIL);
  }

  private Optional<String> refuse(Tenant tenant, String provider, String reason) {
    log.warn("Delegated login refused for tenant {} and provider {}: {}", tenant.getName(),
        provider, reason);
    return Optional.empty();
  }

  private List<TenantLoginProvider> listProviders(Tenant tenant) {
    return providers.list(TenantLoginProviderFilter.builder().tenant(tenant).build());
  }

  private List<DelegatedAccessExternalProvider> providers(Tenant tenant) {
    return listProviders(tenant).stream().map(this::map).filter(Objects::nonNull).toList();
  }

  private Optional<TenantLoginProvider> provider(Tenant tenant, String name) {
    return listProviders(tenant).stream()
        .filter(lp -> Boolean.TRUE.equals(lp.isEnabled()) && name.equals(lp.getName())).findFirst();
  }

  private DelegatedAccessExternalProvider map(TenantLoginProvider provider) {
    if (!Boolean.TRUE.equals(provider.isEnabled())) {
      return null;
    }
    if (provider.getProviderType() == TenantLoginProviderProviderTypeOptions.GOOGLE) {
      return mapGoogle(provider);
    }
    if (provider.getProviderType() == TenantLoginProviderProviderTypeOptions.SAML) {
      return mapSaml(provider);
    }
    return null;
  }

  /**
   * A SAML provider without IdP SSO URL, entity ID or certificate is not offered.
   *
   * The SP entity ID is {@code entity_id} of the metadata JSON, or the provider name (as in PHP).
   */
  private DelegatedAccessExternalProvider mapSaml(TenantLoginProvider provider) {
    String ssoUrl = provider.getSamlIdpSsoUrl().orElse("");
    String idpEntityId = provider.getSamlIdpEntityId().orElse("");
    String certificate = provider.getSamlIdpCert().orElse("");
    if (ssoUrl.isBlank() || idpEntityId.isBlank() || certificate.isBlank()) {
      log.warn("SAML provider {} disabled: IdP SSO URL, entity ID or certificate missing",
          provider.getUid());
      return null;
    }
    return new SamlDelegatedAccessProvider(provider.getName(), ssoUrl,
        spEntityId(provider).orElse(provider.getName()), idpEntityId, certificate,
        Boolean.TRUE.equals(provider.isDirectAccess()), Clock.systemUTC());
  }

  private static Optional<String> spEntityId(TenantLoginProvider provider) {
    return provider.getMetadata().flatMap(json -> {
      try {
        JsonNode value = MAPPER.readTree(json).path("entity_id");
        return value.isTextual() && !value.textValue().isBlank() ? Optional.of(value.textValue())
            : Optional.empty();
      } catch (Exception ex) {
        return Optional.empty();
      }
    });
  }

  private DelegatedAccessExternalProvider mapGoogle(TenantLoginProvider provider) {
    return new GoogleDelegatedAccessProvider(provider.getName(),
        provider.getPublicKey().orElse("-"), provider.getPrivateKey().orElse("-"),
        Boolean.TRUE.equals(provider.isDirectAccess()));
  }
}
